class ItemClass(IntEnum):
    """These are the possible item classes."""
    BAGITEM = 0x0
    MULTIBAGITEM0 = 0x1
    MULTIBAGITEM1 = 0x2
    MULTIBAGITEM2 = 0x3
    SPECIALBAGITEM = 0x4
    POKETCHAPP = 0x5
    BADGE = 0x6
    ACCESSORY = 0x7
    REMOTE0 = 0xC
    REMOTE1 = 0xD
    SPECIAL = 0xE

@dataclass(frozen=True)
class ItemData:
    label: str
    id: int
    clas: ItemClass
    count: int = 1
    classification: ItemClassification = ItemClassification.filler
    data_id: int | None = None

    def get_raw_id(self) -> int:
        clas = self.clas
        id = self.id
        if self.count > 1:
            top_bit = id >> 8
            clas += top_bit + 1
            id = id & 0xFF | self.count << 8
        return clas << 12 | id

